mapper.select:
select * from ( select a.*, rownum rnum from ( select lo.lot_out_id as stock_id, lo.lot_in_id, p.product_name, p.status as product_type, w.warehouse_name, w.warehouse_id, li.expiration_date, lo.quantity, lo.shipped_date as days_left from lot_out lo join lot_in li on lo.lot_in_id = li.lot_in_id join inbound_detail id on li.inbound_detail_id = id.inbound_detail_id join product p on id.product_id = p.product_id join warehouse w on lo.warehouse_id = w.warehouse_id
order by lo.shipped_date desc ) a )
where rnum >= #{startRow} and rnum <= #{endRow}
